          drinks: "\u05D9\u05D9\u05DF, \u05D1\u05D9\u05E8\u05D4 \u05D5\u05DE\u05E9\u05E7\u05D0\u05D5\u05EA",
          chocolate: "\u05E9\u05D5\u05E7\u05D5\u05DC\u05D3 \u05D5\u05DE\u05DE\u05EA\u05E7\u05D9\u05DD",
